import{z as s,x as p,o as n,c as A,q as i,j as o,D as e,d as t,s as B,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"风险投资：分阶段与合同","description":"","frontmatter":{"title":"风险投资：分阶段与合同","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/venture-capital-staging.md","filePath":"econ/venture-capital-staging.md","lastUpdated":1791063341000}'),d={name:"econ/venture-capital-staging.md"};function C(m,a,c,D,h,u){const r=p("Mermaid");return n(),A("div",null,[a[2]||(a[2]=i('<h1 id="风险投资-分阶段与合同" tabindex="-1">风险投资：分阶段与合同 <a class="header-anchor" href="#风险投资-分阶段与合同" aria-label="Permalink to &quot;风险投资：分阶段与合同&quot;">​</a></h1><div class="epigraph"><p>风险投资不靠还本纪律，而靠分阶段注资、可转换优先股与控制权随里程碑转移：把放弃期权留在投资人手里，把努力激励留在创业者手里。</p><footer>—— Sahlman, Journal of Financial Economics 1990；Gompers, Journal of Finance 1995；Kaplan and Strömberg, Review of Economic Studies 2003</footer></div><p><a href="/econ/lbo-private-equity">上一课</a>的对象是有 FCF 的成熟资产。本课缺口是相反的企业：负现金、软信息、增长期权极大。VC 用 staging 买实物期权，用合同切现金流与控制权。不重写 LBO 杠杆，不把 IPO 抑价课再推一遍——只接到退出。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>银行债与 LBO 要求可验证的偿还。创业企业没有。Sahlman：VC 是合同与分阶段的中介。Gompers：分阶段缩短检查间隔，像短债检查，但不要求付息——不续投就是关停期权。Kaplan–Strömberg：实际合同把现金流权、表决权、清算优先、董事会席位随可验证信号分开，接近 Aghion–Bolton 的状态依存控制，而不是 MM 切片。缺口是把实物期权估值课的「分阶段」写成金融合同，而不是再画一次决策树。</p><p><span class="marginnote">可转优先：下行像债（清算优先），上行转股。与 Stein 后门权益同族，但对象是私人企业与控制权，不是公开柠檬单独一句。</span></p><p><span class="marginnote">术语翻译：分阶段注资（staging）就是把原本一次性给的钱，切成按里程碑解锁的几笔。每一轮都附带「下一轮可以不给」的选项，检查频率由资金节奏决定——钱给得越碎，看得越勤。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>staging：每轮按里程碑，放弃成本是已沉没的轮次，保留的是不付下一轮 \\(I\\)。这正是 Dixit–Pindyck 的等待/放弃。联合投资（syndication）分担资本与信息，也制造协调（谁领投）。退出：IPO 或出售；<a href="/econ/ipo-underpricing-theory">IPO 抑价</a>解释公开那一次，本课只要：退出把私人合同转成公众治理，双层股权常在此时写入。</p><p>与优序：没有内部资金，债容量近零，股权（优先股）是主菜单。柠檬仍在，VC 用监测与分阶段降低，而不是靠公开市场定价。</p><p><span class="marginnote">数字实例：总投资 3000 万拆成三轮各 1000 万。投完第二轮发现产品不行，VC 已沉没 2000 万、止损不再投第三轮；若当初一次性投足 3000 万，就没有这个「中途下车」的选项。</span></p>',11)),(n(),o(l,null,{default:e(()=>[B(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20OPT%5B%22%E5%A2%9E%E9%95%BF%E6%9C%9F%E6%9D%83%20%2F%20%E8%B4%9F%20FCF%22%5D%20--%3E%20STG%5B%22%E5%88%86%E9%98%B6%E6%AE%B5%22%5D%0A%20%20STG%20--%3E%20ABAND%5B%22%E4%B8%8D%E7%BB%AD%E6%8A%95%20%3D%20%E6%94%BE%E5%BC%83%22%5D%0A%20%20CON%5B%22%E5%8F%AF%E8%BD%AC%E4%BC%98%E5%85%88%20%2B%20%E6%8E%A7%E5%88%B6%E6%9D%83%22%5D%20--%3E%20AB%5B%22%E7%8A%B6%E6%80%81%E4%BE%9D%E5%AD%98%E6%9D%83%E5%A8%81%22%5D%0A%20%20EXIT%5B%22IPO%20%2F%20%E5%B9%B6%E8%B4%AD%22%5D%20--%3E%20PUB%5B%22%E5%85%AC%E4%BC%97%E6%B2%BB%E7%90%86%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"薪酬：创业者股权高，但稀释与归属（vesting）管理努力。多任务：可验证的增长指标会挤出产品安全与会计诚实——同一 Holmström 问题。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"机制是用合同复制「短债+董事会+期权」在无债企业里的功能。控制权在坏信号时转向 VC（可换 CEO），好信号时创业者保留。现金流权用优先清算保护下行，避免创业者赌大把 VC 当债来转移。这与风险转移课同方向，工具换成优先股而不是限制性条款银行债。",-1)),(n(),o(l,null,{default:e(()=>[B(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20S%5B%22%E5%AD%A3%E5%BA%A6%E9%87%8C%E7%A8%8B%E7%A2%91%E4%BF%A1%E5%8F%B7%22%5D%20--%3E%7C%22%E8%BE%BE%E6%A0%87%22%7C%20F%5B%22%E5%88%9B%E5%A7%8B%E4%BA%BA%E4%BF%9D%E7%95%99%E6%8E%A7%E5%88%B6%E6%9D%83%22%5D%0A%20%20S%20--%3E%7C%22%E6%9C%AA%E8%BE%BE%E6%A0%87%22%7C%20V%5B%22VC%20%E6%8B%BF%E4%B8%8B%E8%91%A3%E4%BA%8B%E4%BC%9A%E4%B8%BB%E5%AF%BC%E6%9D%83%22%5D%0A%20%20V%20--%3E%20C%5B%22%E6%9C%89%E6%9D%83%E6%92%A4%E6%8D%A2%20CEO%20%2F%20%E8%B0%83%E6%95%B4%E6%96%B9%E5%90%91%22%5D%0A%20%20F%20--%3E%20N%5B%22%E4%B8%8B%E8%BD%AE%E6%8C%89%E6%9B%B4%E9%AB%98%E4%BC%B0%E5%80%BC%E8%9E%8D%E8%B5%84%22%5D%0A%20%20C%20--%3E%7C%22%E6%94%B9%E5%96%84%22%7C%20N%0A%20%20C%20--%3E%7C%22%E6%8C%81%E7%BB%AD%E6%81%B6%E5%8C%96%22%7C%20L%5B%22%E6%B8%85%E7%AE%97%E4%BC%98%E5%85%88%E6%9D%83%E4%BF%9D%E4%BD%8F%E4%B8%8B%E8%A1%8C%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p><span class="marginnote">常见误区：初学者容易以为控制权转移是「公司失败之后」才发生。实际上合同把它写成因可验证信号（收入、里程碑）触发的状态依存条款——坏信号一到，VC 立即有权换 CEO，不必等到清算那天。</span></p><p>与关系借贷：VC 生产软信息、跨期补贴存活轮次，套牢也存在（内部轮次定价）。联合投资与声誉减轻套牢。</p><h3 id="不是把-vc-回报当成项目-npv-的证明" tabindex="-1">不是把 VC 回报当成项目 NPV 的证明 <a class="header-anchor" href="#不是把-vc-回报当成项目-npv-的证明" aria-label="Permalink to &quot;不是把 VC 回报当成项目 NPV 的证明&quot;">​</a></h3><p>存活偏差与权力法则回报使平均 IRR 难读。资本预算对创业项目仍是概率加权的 FCFF 加放弃期权，不是套用上一家独角兽的倍数。倍数课的收入倍数在此最危险。</p><p><span class="marginnote">Kaplan–Strömberg <em>RES</em> 2003 把合同条款映射到金融合同理论，是本课的许可证：现实合同真的在切控制权，不只切现金流。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把本课写成创业手册。下一课双层股权：创始人在 IPO 后仍要留权威，把 VC 阶段的控制权配置延伸到公众市场。LLSV 则把法律对中小股东的保护写成国别差异。</p><p>后课默认：VC 用 staging 持有放弃期权，用优先股与控制权配置激励；对象是无债容量的增长期权企业，与 LBO 对偶。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分阶段 = 可执行的放弃期权；不续投替代还本。</li><li>可转优先与状态依存控制权接近不完全合同理论，而不是 MM 纯切片。</li><li>退出接到 IPO 与双层股权；不要用独角兽倍数替代 NPV。</li><li>出处：Sahlman, <em>JFE</em> 1990；Gompers, <em>JF</em> 1995；Kaplan and Strömberg, <em>RES</em> 2003。</li></ul>',10))])}const F=s(d,[["render",C]]);export{f as __pageData,F as default};
